    "content": "新华社北京8月23日电（记者王明玉）应中国教育国际交流协会邀请，支持中国治沙事业的美国友人“赛考斯”（本名罗纳德·萨科尔斯基）23日凌晨抵达北京，将于8月23日至9月1日访问北京、内蒙古、河南三地，再续一段跨越山海的中美民间友谊。 在华期间，萨科尔斯基将与全国劳动模范殷玉珍共同植树，同曾任教学校师生座谈互动，还将参加中美教师交流活动、参观外交部新闻发布厅及相关历史文化地标等。他说，此次重返中国，激动又欣喜，期待与昔日友人、师生再度相聚，续写这段故事。 1999年，跟随“中美教师交换项目”来到中国任教的美国教师萨科尔…"
