    "author": "林威",
    "description": "新华社渥太华8月22日电（记者林威）加拿大总理卡尼22日发表全国电视讲话，就加美贸易谈判破裂全面阐明加方立场。卡尼宣布，鉴于美国对价值200亿美元的加拿大商品征收50%的关税，加拿大的等额报复性关税计划于9月8日正式生效执行。 卡尼表示，反制关税将涵盖乳制品、钢铁、家电、纸浆与造纸以及电子产品等多个领域。 在谈及谈判为何在最后时刻中断时，卡尼说，虽然本周早些时候双方曾接近达成互利共赢的协议，但美方在最后一刻提出了不经济、不公平且极大损害…",
    "content": "新华社渥太华8月22日电（记者林威）加拿大总理卡尼22日发表全国电视讲话，就加美贸易谈判破裂全面阐明加方立场。卡尼宣布，鉴于美国对价值200亿美元的加拿大商品征收50%的关税，加拿大的等额报复性关税计划于9月8日正式生效执行。 卡尼表示，反制关税将涵盖乳制品、钢铁、家电、纸浆与造纸以及电子产品等多个领域。 在谈及谈判为何在最后时刻中断时，卡尼说，虽然本周早些时候双方曾接近达成互利共赢的协议，但美方在最后一刻提出了不经济、不公平且极大损害加拿大利益的新条款，试图限制加拿大与其他国家达成新的贸易协议的能力以及加拿大对其…"
