    "description": "据泰媒报道，当地时间22日20时起，泰国南部三府那拉提瓦、也拉、北大年相继发生爆炸、纵火等恶性事件，已造成至少两人受伤。那拉提瓦军方特遣队宣布全府从当天22时15分至23日6时实施宵禁。 新华社曼谷8月22日电（记者林淑婷 常天童）据泰媒报道，当地时间22日20时起，泰国南部三府那拉提瓦、也拉、北大年相继发生爆炸、纵火等恶性事件，已造成至少两人受伤。那拉提瓦军方特遣队宣布全府从当天22时15分至23日6时实施宵禁。",
