    "content": "新华社基辅8月22日电 乌克兰总统泽连斯基22日在社交媒体发文说，他当天与法国总统马克龙通电话，法国已同意加快向乌克兰供应法制武器装备与导弹，并将向乌方提供相关导弹的生产许可。 泽连斯基说，他向马克龙通报了近期乌境内遭袭情况，表示防空系统是当前乌方首要需求。马克龙表示，愿协助乌方与拥有“爱国者”防空导弹的其他伙伴国进行沟通。 法国总统马克龙当天在社交媒体也发文，称对乌克兰购物中心遭袭击造成大量平民伤亡感到震惊。他表示，已向泽连斯基确认法国将加强对乌克兰防空力量的支持，特别是向乌提供拦截导弹。 据乌克兰通讯社22日报…"
