    "content": "连日来，伴随着更多事实的披露，“两人三座”一事的讨论已远远超出个案范畴，更多具有重思规则的意义。随着当事人母亲接受采访介绍了更多内情，舆论讨论也从“花钱能不能多占座”转向另一个议题：当家长无力贴身护送，铁路该如何保障未成年人的单独出行？ 据当事人的澄清，两个未成年女孩趁着暑假来到上海和父母团聚，返乡时，因为母亲实在请不出假，无法陪着坐27个小时的火车返乡；而按照铁路购票规则，儿童票不能独立下单，必须绑定成人票购买；如果先一起买，再退掉成人票，仅保留儿童票，铁路方面却提示，此时列车员有权要求孩子下车——此路不通。同时…"
