    "title": "银兰高铁：6小时深夜鏖战 保障暑运畅通",
    "link": "http://www.news.cn/20260822/313f43c7f632487c8efabd7f2aa75435/c.html",
    "pub_date": "2026-08-22 22:15:57",
    "author": "卢书剑",
    "description": "暑运期间，银兰高铁客流、车流持续高位运行，线路设备负荷显著增加。为保障列车安全平稳运行，近日，中卫工务段抢抓高铁夜间“天窗”时间，在中卫南站开展道岔换轨施工作业。 施工现场机械轰鸣、人头攒动，作业人员严守毫米级标准，精准切轨、有序更换、高效焊接、打磨复检。经过6个小时鏖战，换轨任务圆满完成，大幅提升了站内线路设备的稳定性和平顺性。 作者：卢书剑 丁波 新华社音视频部制作",
