    "content": "近日，有家长在问政四川平台投诉：“娃娃高考后（准大学生）邮寄档案（纸质档案投递），但当地邮政却要求办联通电话卡。”8月21日，泸州市邮政管理局进行了回应。 还有一名学生也在8月3日投诉称：他是2026届高三毕业生，8月2日前往中国邮政网点办理高考毕业生档案邮寄手续。网点工作人员要求必须先办理电话卡，才能受理档案寄递业务，实行业务捆绑。 在本人明确表示暂不需要办理新电话卡，计划入学后自行选购号码的情况下，工作人员仍坚持办卡是办理档案手续的前置条件，导致其进退两难。 8月21日，泸州市邮政管理局回应称：该局已下发监管提…"
