    "description": "新华社赫尔辛基8月22日电（记者朱昊晨 徐谦）斯德哥尔摩消息：瑞典卡罗琳医学院和斯德哥尔摩大学研究人员开发出一种新工具，可通过分析细胞的基因活性来估算细胞的生物学年龄，未来有望为研究衰老机制和开发相关疗法提供支持。 卡罗琳医学院近日发布新闻公报说，衰老是癌症、心血管疾病和神经退行性疾病等多种疾病的重要风险因素，但目前仍缺乏能够可靠测量细胞衰老速度的方法。 研究人员开发的新工具名为“Pasta”，它通过分析细胞中哪些基因处于活跃状态、哪些…",
    "content": "新华社赫尔辛基8月22日电（记者朱昊晨 徐谦）斯德哥尔摩消息：瑞典卡罗琳医学院和斯德哥尔摩大学研究人员开发出一种新工具，可通过分析细胞的基因活性来估算细胞的生物学年龄，未来有望为研究衰老机制和开发相关疗法提供支持。 卡罗琳医学院近日发布新闻公报说，衰老是癌症、心血管疾病和神经退行性疾病等多种疾病的重要风险因素，但目前仍缺乏能够可靠测量细胞衰老速度的方法。 研究人员开发的新工具名为“Pasta”，它通过分析细胞中哪些基因处于活跃状态、哪些基因处于不活跃状态，能够估算细胞的生物学年龄。为开发这一工具，研究人员首先分析了…"
