    "description": "伊斯兰堡口岸距阿富汗西部赫拉特市约120公里，是阿富汗与伊朗之间的重要陆路口岸，也是连接两国的主要商贸和交通通道，每天有大量人员和货物经此往来。 记者在这里观察到，来往的旅客手提行李箱面带疲惫，客商推着小车行色匆匆，满载货物的卡车排队通关……但一片繁忙景象背后，是美伊冲突给边境贸易带来的连锁反应。 记者：胥舒骜、张艺缤 报道员：阿里亚 新华社音视频部制作",
