    "link": "https://www.chinanews.com.cn/jk/2026/08-22/10682477.shtml",
    "pub_date": "2026-08-22 21:45:54",
    "author": "",
    "description": "是不是一关灯就躺着刷手机，越刷越停不下来？黑暗里看手机，伤害都是悄悄累积的，很多人等到难受才后悔，损伤已经不可逆！关灯玩手机有三大致命伤害，三条底线一定要记住。",
