    "description": "中新社福州8月22日电 (记者 张金川 张丽君)受今年第20号台风“简拉维”影响，福建省防汛抗旱指挥部22日15时启动防台风四级应急响应。",
    "content": "中新社福州8月22日电 (记者 张金川 张丽君)受今年第20号台风“简拉维”影响，福建省防汛抗旱指挥部22日15时启动防台风四级应急响应。"
