    "content": "新华社突尼斯8月22日电（记者周昊瑾）据突尼斯媒体22日报道，一艘载有移民的船只21日晚在突尼斯东南部海域倾覆，目前已找到4具遗体，另有10余人失踪。 报道说，当地海事中心接到求救信号，称一艘载有至少十多人的船只21日晚在本格尔丹海岸附近遇险。救援人员救起两名男子，其中一人被送往当地医院，情况危急。海上安全部队和获准参与救援的渔船正在事发海域继续搜救。 根据初步报告和幸存者的说法，这艘船当时正驶往意大利，途中引擎出现故障，随后倾覆。 突尼斯位于非洲大陆北端，与意大利等欧洲国家隔地中海相望。近年来，经由突尼斯偷渡到意…"
