    "description": "新华社德黑兰8月22日电（记者沙达提 陈霄）据伊朗迈赫尔通讯社22日报道，伊朗国防部发言人礼萨·塔拉埃-尼克接受伊朗国家电视台采访时表示，过去一年来，伊朗武器和国防装备的产量翻了一番。 塔拉埃-尼克说，在去年6月与美以持续12天的冲突结束后，伊朗的武器和国防装备产量整体翻了一番，部分战时优先列装的战略装备的产量甚至增长了三倍以上。这与美国和以色列领导人一度声称“伊朗国防生产将陷入停滞”的说法截然相反。 他还表示，为保守军事机密，部分装备…",
    "content": "新华社德黑兰8月22日电（记者沙达提 陈霄）据伊朗迈赫尔通讯社22日报道，伊朗国防部发言人礼萨·塔拉埃-尼克接受伊朗国家电视台采访时表示，过去一年来，伊朗武器和国防装备的产量翻了一番。 塔拉埃-尼克说，在去年6月与美以持续12天的冲突结束后，伊朗的武器和国防装备产量整体翻了一番，部分战时优先列装的战略装备的产量甚至增长了三倍以上。这与美国和以色列领导人一度声称“伊朗国防生产将陷入停滞”的说法截然相反。 他还表示，为保守军事机密，部分装备系统暂未对外展示，但军队指挥官了解包括弹道导弹、巡航导弹、无人机及防空系统在内的…"
