    "content": "新华社德黑兰8月22日电（记者沙达提 陈霄）据伊朗伊斯兰共和国通讯社22日报道，在伊朗伊斯兰议会议长卡利巴夫访问伊拉克期间，伊拉克方面提出，希望伊朗给伊拉克油轮发放通过霍尔木兹海峡的特别通行许可。 报道说，伊拉克此前已通过各种渠道多次向伊朗提出该请求，伊朗目前允许部分伊拉克油轮通过霍尔木兹海峡。 报道还说，美国和以色列对伊朗发动军事行动以来，由于美以联合军事行动造成的安全威胁，以及伊朗为阻止敌对船只通过而采取的安全措施，霍尔木兹海峡几乎完全对国际航运关闭。 卡利巴夫于19日抵达伊拉克首都巴格达，先后会见伊拉克总理扎…"
