    "content": "新华社香港8月22日电（奚天麒）香港特区政府22日下午在皇岗口岸港方口岸区举行迄今最大规模的人流车流压力测试，首次与深圳相关单位合作开展联合演练，动员超过1万名公务员及近千辆私家车参与。 这是8月22日在皇岗口岸港方口岸区拍摄的人流压力测试。新华社发（吕小炜摄） 参与演练的公务员按指示乘坐公共交通工具抵达口岸，完成出入境程序后有序离开。演练期间，参与人员乘用公共交通营办商车辆，进行超过400班次的循环接驳测试，模拟客流高峰时段人流与车流集中进出口岸的实际场景。 演练首次对旅客通关“合作查验”自助通道进行实际测试。参…"
