    "pub_date": "2026-08-22 20:32:18",
    "author": "",
    "description": "中新网北京8月22日电 (记者 孙自法)作为中国人工智能赋能科学研究(AI for Science，简称AI4S，也称科学智能)领域最高规格的学术盛会，2026科学智能大会8月21日至22日在北京中关村成功举办。通过国际科技合作专题交流研讨，大会为中国深度参与并引领全球科学智能合作提供“中国方案”。",
    "content": "中新网北京8月22日电 (记者 孙自法)作为中国人工智能赋能科学研究(AI for Science，简称AI4S，也称科学智能)领域最高规格的学术盛会，2026科学智能大会8月21日至22日在北京中关村成功举办。通过国际科技合作专题交流研讨，大会为中国深度参与并引领全球科学智能合作提供“中国方案”。"
