    "content": "新华网福州8月22日电（记者 唐斓）闽东大地，山海相拥。近日，“活力中国调研行”记者团走进宁德沿海乡村，看海上牧场，听渔村新事。在这里，渔业转型发展、文旅蓬勃兴起，一幅产业兴旺、生态宜居的画卷，正在碧海之畔徐徐铺展。 一条鱼，解锁海上富民产业链 这是三都澳海域海上渔排。新华网记者 唐斓 摄 碧波浩渺的三都澳海域上，一座座深水网箱错落排布，成群大黄鱼在网箱内往来游弋，现代化“海上牧场”的壮阔景象跃然眼前。 全国人工养殖大黄鱼，十有八九产自宁德。2025年，当地大黄鱼总产量达22.24万吨，全产业链总产值突破200亿元…"
