    "content": "新华社布拉迪斯拉发8月22日电（记者孟凡宇 刘昊东）“中国与维谢格拉德集团（V4）国家关系：前行之路”研讨会21日在斯洛伐克首都布拉迪斯拉发举行，与会者围绕V4集团的现状与展望、各国与中国如何更好开展务实共赢合作等问题进行了深入交流探讨。 8月21日，在斯洛伐克首都布拉迪斯拉发，嘉宾在研讨会现场合影。 新华社发 研讨会由中国复旦大学中欧关系研究中心和斯洛伐克智库分析—战略—替代方案研究所共同主办。来自中国、维谢格拉德集团（波兰、匈牙利、捷克、斯洛伐克）和德国等国的30余名高校学者、智库专家、政府官员以及企业界人士参…"
