    "title": "秀我中国丨世人从未忘记少年将军霍去病",
    "link": "http://www.news.cn/20260822/6079062c85f443a29187e263040923a2/c.html",
    "pub_date": "2026-08-22 20:05:51",
    "author": "陈思,林珑",
    "description": "“匈奴未灭，无以家为也。”说出这句话的少年将军霍去病，去世时年仅24岁。两千多年来，世人从未忘记他：有帝王为他“发属国玄甲军”“为冢象祁连山”，有书法家为他“病”字少一点，有少年为他重燃斗志。新华社记者带您走进位于咸阳兴平的茂陵博物馆，探迹霍去病墓，感受这位少年英雄滚烫的家国赤诚。 作者：陈思 林珑 新华社音视频部制作",
    "content": "“匈奴未灭，无以家为也。”说出这句话的少年将军霍去病，去世时年仅24岁。两千多年来，世人从未忘记他：有帝王为他“发属国玄甲军”“为冢象祁连山”，有书法家为他“病”字少一点，有少年为他重燃斗志。新华社记者带您走进位于咸阳兴平的茂陵博物馆，探迹霍去病墓，感受这位少年英雄滚烫的家国赤诚。 作者：陈思 林珑 新华社音视频部制作"
