    "content": "新华社武汉8月22日电（记者张阳）“特地到这里避暑，一下车就感觉非常凉爽，自然生态也很好。”在湖北省鹤峰县屏山旅游景区，来自湖北宜昌的游客肖晴站在景区的栈道上，俯瞰高耸的峡谷和谷底的碧水。 赏奇山秀水，观峡谷幽境。屏山峡谷夏季平均气温24℃，得天独厚的山水资源与凉爽宜人的气候，吸引八方游客前来避暑游玩。据统计，屏山旅游景区今年暑期客流量较去年同期增长30%，截至目前已接待近40万名游客。 游船穿行峡谷间。新华社发（唐雪琴 摄） 景区推出多项优惠措施，助力暑期消费持续升温。“我们店不仅上线了多款特色套餐，中高考生还可…"
