    "description": "8月24日，冥王星“降级”整整20年。2006年的这一天，它退出太阳系“九大行星”之列，被归为矮行星。20年来，它的“身份”降了级，人类对它的认识却不断升级。其间，人类探测器近距离飞掠冥王星，让这个望远镜中的暗弱光点，变成一个拥有冰原、山脉，甚至可能藏着地下海洋的复杂世界。 冥王星如何被发现，又为何被“降级”？之后，人类又看到了怎样的冥王星？ 中国科学院紫金山天文台科普主管王科超介绍，1929年，美国天文学家克莱德·汤博用33厘米口径天…",
    "content": "8月24日，冥王星“降级”整整20年。2006年的这一天，它退出太阳系“九大行星”之列，被归为矮行星。20年来，它的“身份”降了级，人类对它的认识却不断升级。其间，人类探测器近距离飞掠冥王星，让这个望远镜中的暗弱光点，变成一个拥有冰原、山脉，甚至可能藏着地下海洋的复杂世界。 冥王星如何被发现，又为何被“降级”？之后，人类又看到了怎样的冥王星？ 中国科学院紫金山天文台科普主管王科超介绍，1929年，美国天文学家克莱德·汤博用33厘米口径天体照相仪搜寻未知行星。他拍摄同一天区，比对不同日期底片，寻找恒星背景中会“挪位置…"
