    "author": "邓瑞璇",
    "description": "新华社广州8月22日电（记者邓瑞璇）伴随悠长的汽笛鸣响，“大湾区伊敦号”游轮22日从广州南沙国际邮轮母港启程，奔赴深圳蛇口国际邮轮母港，标志着“湾区明珠双城海上游”全新航线正式首航，穗深双向常态化海上文旅航线正式开通。 游轮以“海上看城”的全新视角，穿越港珠澳大桥和深中通道两大世界级超级工程，途经虎门大桥、内伶仃岛、南沙天后宫、深圳前海博物馆、香港大屿山等16个湾区核心地标，珠海、澳门城市滨海天际线尽收眼底。游轮上还上演岭南非遗主题演艺…",
    "content": "新华社广州8月22日电（记者邓瑞璇）伴随悠长的汽笛鸣响，“大湾区伊敦号”游轮22日从广州南沙国际邮轮母港启程，奔赴深圳蛇口国际邮轮母港，标志着“湾区明珠双城海上游”全新航线正式首航，穗深双向常态化海上文旅航线正式开通。 游轮以“海上看城”的全新视角，穿越港珠澳大桥和深中通道两大世界级超级工程，途经虎门大桥、内伶仃岛、南沙天后宫、深圳前海博物馆、香港大屿山等16个湾区核心地标，珠海、澳门城市滨海天际线尽收眼底。游轮上还上演岭南非遗主题演艺、近景魔术等节目，为游客提供海景观光、休闲娱乐、文化演艺等多样化体验。 “之前都…"
