    "content": "新华社安卡拉8月22日电 热点问答｜推动通缉内塔尼亚胡 土以交恶向何处去 新华社记者王腾飞 庞昕熠 土耳其司法部长阿金·居尔莱克21日说，作为对以色列武装干预向加沙地带运送人道主义援助物资船队的司法程序的一部分，土政府正推动国际刑警组织针对以总理内塔尼亚胡等人发布红色通缉令。土耳其这一举动释放什么信号？与以色列缘何交恶？局势将如何发展？ 释放什么信号 居尔莱克在社交媒体上发文说，以“种族灭绝罪”对内塔尼亚胡等人的逮捕令已于7月由土耳其法院发出。之后，土司法部据此要求内政部推动发布针对内塔尼亚胡等人的红色通缉令，以便…"
