    "content": "新华社呼和浩特8月22日电（记者王雪冰、安路蒙）当前，我国算力规模快速增长，算力设备向高能效方向升级，算力载体绿色化转型进展积极，算电协同从理念走向实践，算力网、词元经济、算力出海等新模式新业态成为新增长极。 这是记者22日从内蒙古自治区呼和浩特市举行的2026绿色算力（人工智能）大会上获得的最新消息。大会开幕式上，中国信息通信研究院副院长敖立发布《绿色算力发展研究报告（2026年）》。 报告指出，在算力设备绿色化方面，我国算力设备加速向高能效方向迭代升级。截至2026年6月底，我国智能算力规模达2185EFLOP…"
