    "content": "“稳—航—探—作”一体化作业级近海智能无人艇“埕安一号”，近日在渤海湾埕海1-1人工岛海域正式投运，并在三级海况下完成首轮近海测试。 “埕安一号”由中国石油大港油田公司牵头，联合中国石油集团工程技术研究有限公司、河海大学自主研制，标志着我国近海油气设施巡检迈入智能化无人作业新阶段。 近海智能无人艇“埕安一号”下水开展作业。（受访对象供图） 渤海湾浅海区域风浪流交织，海底油气管线、电缆密集，传统有人巡检面临作业窗口有限、人员风险高、成本较大等痛点。“埕安一号”采用双体悬浮减振上甲板稳定构型，设计续航不低于12小时，可…"
