    "description": "新华社天津8月22日电（记者 周润健）“离离暑云散，袅袅凉风起。”北京时间8月23日10时19分将迎来处暑节气，标志着我国大部地区逐渐进入气象意义上的秋天。巧合的是，这一天也是末伏最后一天，今年长达40天的三伏即将落幕，要出伏了。 从节气规律来看，入伏多在小暑前后，出伏都在立秋过后，时间多靠近处暑，有的年份还会晚于处暑。民俗专家、天津社会科学院研究员王来华介绍，民间习惯以处暑为参照，区分早、晚出伏：出伏在处暑前为“早出伏”，出伏在处暑后…",
    "content": "新华社天津8月22日电（记者 周润健）“离离暑云散，袅袅凉风起。”北京时间8月23日10时19分将迎来处暑节气，标志着我国大部地区逐渐进入气象意义上的秋天。巧合的是，这一天也是末伏最后一天，今年长达40天的三伏即将落幕，要出伏了。 从节气规律来看，入伏多在小暑前后，出伏都在立秋过后，时间多靠近处暑，有的年份还会晚于处暑。民俗专家、天津社会科学院研究员王来华介绍，民间习惯以处暑为参照，区分早、晚出伏：出伏在处暑前为“早出伏”，出伏在处暑后为“晚出伏”。今年出伏在8月24日，属于晚出伏。 关于出伏，民间流传着不少有趣农…"
