    "content": "8月22日，观众在参观第十届海峡两岸艺术名家邀请展。新华社记者 马欣然 摄 新华社台北8月22日电（记者马欣然、黄扬）第十届海峡两岸艺术名家邀请展22日下午在台北开幕，集中展出两岸260余位书画家创作的超400件佳作，共叙同根同脉的文化情谊。 书画铺陈，印章点缀，来自两岸的艺术精品会聚一堂。其中，画作《两岸同脉图》成为此次展览最受瞩目的作品之一。该画由20位两岸知名艺术家联袂创作、共同署名，吸引众多观众驻足观赏。 《两岸同脉图》以日出东方为背景，红日映照下的山川江河气象万千、磅礴壮阔。大陆艺术家张惠臣、王书平、唐云…"
