    "author": "李恒,田晓航",
    "description": "新华社北京8月22日电 题：换季养生，这些健康误区你中了几个 新华社记者李恒、田晓航 处暑即将来临，暑热渐消，换季养生广受关注。 专家提示，季节交替时期是呼吸道疾病与骨骼肌肉系统疾病的高发期。一些健康误区要注意科学辨识，防止因混淆症状而造成误判、延误治疗。 误区一：流感就是普通感冒，扛一扛就过去了 中国疾控中心研究员王富珍表示，流感是由流感病毒引起的急性呼吸道传染病，得了流感全身性症状相对较重，尤其是儿童、老年人、慢性病患者，发生重症或…",
    "content": "新华社北京8月22日电 题：换季养生，这些健康误区你中了几个 新华社记者李恒、田晓航 处暑即将来临，暑热渐消，换季养生广受关注。 专家提示，季节交替时期是呼吸道疾病与骨骼肌肉系统疾病的高发期。一些健康误区要注意科学辨识，防止因混淆症状而造成误判、延误治疗。 误区一：流感就是普通感冒，扛一扛就过去了 中国疾控中心研究员王富珍表示，流感是由流感病毒引起的急性呼吸道传染病，得了流感全身性症状相对较重，尤其是儿童、老年人、慢性病患者，发生重症或其他并发症的风险较高。 相关研究证据表明，每年流感流行可导致全球产生300万至5…"
