    "content": "新华社北京8月22日电 题：处暑遇开学 中医支招守护中小学生健康 新华社记者田晓航、帅才 8月23日将迎来处暑节气，三伏“大幕”也将就此落下。处暑正值夏秋之交，中小学生即将迎来新学期，如何顺应时节变换调适身心，以良好状态投入校园生活？ 中国中医科学院广安门医院儿科主任王波介绍，今年暑热比往年更盛、更持久，叠加40天超长三伏，处暑时节暑热暑湿尚未完全消退，秋燥已悄然生发。儿童脏腑娇嫩、气血薄弱，健康更容易受到季节更迭影响。 昼夜温差逐步加大，冷热交替之下，鼻塞、流涕、咽痛、咳嗽等外感症状容易找上门；残余暑湿困阻脾胃运…"
