    "content": "耕地保护和质量提升法草案完善了高标准农田立项、建设、验收、管护等机制，严格全周期质量管理，健全高标准农田建设工程全周期责任倒查和终身追责机制，要求高标准农田建设的各个环节必须严格按照国家有关规定进行，确保工程质量。 南方周末记者 吕雅萱 责任编辑：杜茂林 2026年8月25日至28日，十四届全国人大常委会第二十四次会议将在北京举行。 8月21日上午，全国人大常委会法制工作委员会举行发言人记者会。全国人大常委会法工委发言人黄海华介绍，届时将继续审议耕地保护和质量提升法草案、律师法修正草案、农业法修订草案等多部法律草案…"
