    "content": "新华社福州8月22日电（记者 张华迎）为防范今年第20号台风“简拉维”可能带来的不利影响，福建省防指8月22日15时启动防台风四级应急响应。 福建省防指要求，沿海各地各有关部门密切关注台风动态，适时启动防台风应急响应，加强会商研判和组织调度，扎实做好防御工作。"
