    "description": "中国「新新海」集装箱货轮抵达俄罗斯摩尔曼斯克。8月20日，俄罗斯摩尔曼斯克港举行首艘中国集装箱船靠港欢迎仪式，庆祝该港首条来自中国的集装箱航线顺利开通。这条货轮于7月19日从天津港出发，共载运约500个装有汽车零部件的集装箱，穿越北极航道抵达摩尔曼斯克港共耗时1个月。本次通航标志着通过北极航道连接中国港口与俄北极圈内最大深水港的定期货物运输业务正式启动。摩尔曼斯克海上贸易港始建于1915年，目前拥有24个货场和15个泊位，年吞吐能力达2…",
    "content": "中国「新新海」集装箱货轮抵达俄罗斯摩尔曼斯克。8月20日，俄罗斯摩尔曼斯克港举行首艘中国集装箱船靠港欢迎仪式，庆祝该港首条来自中国的集装箱航线顺利开通。这条货轮于7月19日从天津港出发，共载运约500个装有汽车零部件的集装箱，穿越北极航道抵达摩尔曼斯克港共耗时1个月。本次通航标志着通过北极航道连接中国港口与俄北极圈内最大深水港的定期货物运输业务正式启动。摩尔曼斯克海上贸易港始建于1915年，目前拥有24个货场和15个泊位，年吞吐能力达2400万吨，是北极地区唯一可实现全年通航并直通世界大洋的综合性港口。摄影师：Dm…"
