    "content": "新华社上海8月22日电（记者陈潇雨）走进位于上海新国际博览中心的第28届亚洲宠物展览会现场，一阵科技新风扑面而来——搭载“猫脸识别”技术的智能喂食器、实时监测心率与活动量的智能胸背、由手机远程操控的陪宠机器人…… 8月20日，第28届亚洲宠物展览会现场，一只宠物猫在树木造型的猫爬架上休息。新华社记者 王翔 摄 透过这些目不暇接的智能产品，一个“它经济”的新趋势浮出水面：当宠物越来越多地被视作“家庭成员”，如何让“毛孩子”更健康、更长久地陪伴自己，成为无数养宠人最牵挂的事。而本届亚宠展上，一批宠物科技企业带来一系列智…"
