    "pub_date": "2026-08-22 16:11:42",
    "author": "林凯",
    "description": "新华社福州8月22日电（记者林凯）22日，以“英雄的弦歌，奔跑的时代”为主题的第九届南安郑成功文化活动周在福建省南安市开幕。100多位台胞会聚民族英雄郑成功的故乡，拜谒进香、追思先贤，共同弘扬郑成功精神。 本次活动周突出城市IP推广、经贸合作、文史学术和民间民俗交流四大板块，助力推动两岸融合发展。简短的开幕式后，两岸嘉宾前往郑成功陵园敬献花篮。全体人员行三鞠躬礼，深切缅怀郑成功收复台湾的历史功绩。 1661年至1662年初，郑成功挥师东…",
    "content": "新华社福州8月22日电（记者林凯）22日，以“英雄的弦歌，奔跑的时代”为主题的第九届南安郑成功文化活动周在福建省南安市开幕。100多位台胞会聚民族英雄郑成功的故乡，拜谒进香、追思先贤，共同弘扬郑成功精神。 本次活动周突出城市IP推广、经贸合作、文史学术和民间民俗交流四大板块，助力推动两岸融合发展。简短的开幕式后，两岸嘉宾前往郑成功陵园敬献花篮。全体人员行三鞠躬礼，深切缅怀郑成功收复台湾的历史功绩。 1661年至1662年初，郑成功挥师东征，反抗民族压迫和外来侵略，驱逐荷兰殖民者，收复台湾，为中华民族立下不朽功勋。“…"
