    "author": "吴思思",
    "description": "新华社南宁8月22日电（记者吴思思）记者从广西壮族自治区水文中心了解到，受第19号台风“紫檀”影响，8月22日13时，明江及支流派连河、思州河，凭祥河等4条河流5个站超警0.31米至2.71米，其中派连河宁明县寨安乡河段出现2014年建站以来实测第二大洪水。自治区水文中心于8月22日6时发布洪水蓝色预警，并于当日13时升级发布洪水黄色预警，提请崇左、防城港及钦州等市沿江区域有关单位及社会公众加强防范，及时避险。 自治区水文中心预测，未来…",
    "content": "新华社南宁8月22日电（记者吴思思）记者从广西壮族自治区水文中心了解到，受第19号台风“紫檀”影响，8月22日13时，明江及支流派连河、思州河，凭祥河等4条河流5个站超警0.31米至2.71米，其中派连河宁明县寨安乡河段出现2014年建站以来实测第二大洪水。自治区水文中心于8月22日6时发布洪水蓝色预警，并于当日13时升级发布洪水黄色预警，提请崇左、防城港及钦州等市沿江区域有关单位及社会公众加强防范，及时避险。 自治区水文中心预测，未来24小时，明江将全线超警，其中明江宁明县那堪镇河段将出现超警0.5米左右的洪水，…"
