    "content": "新华社贵阳8月22日电 22日，2026年亚洲青年攀岩锦标赛在贵州·彩湖国际攀岩中心展开U17组男子、女子攀石项目的争夺。中国选手谭有恬、李美妮和卢一镜分获女子攀石金、银、铜牌。 谭有恬（中）、李美妮（左）和卢一镜在领奖台上合影。主办方供图 同为“10后”的谭有恬、李美妮和卢一镜是近年来中国女子攀岩冉冉升起的三颗新星，三人是中学同学，同出自广东省中山市中山纪念中学。2011年出生的谭有恬今年首次参加世青赛便在U17女子攀石中摘金，此番回到亚洲舞台再次展现实力，成为22日决赛中唯一完攀全部4条线路的女选手，成功夺金。…"
