    "content": "8月19日至23日，第28届亚洲宠物展览会在上海新国际博览中心举行。 本届展会展览面积达32万平方米，汇聚2600余家展商，规模再创新高。2000多款宠物新品首发首秀，“人宠共用”正在引领宠物消费的新潮流，推动产业链条不断延伸，以科技创新推动行业发展。 作者：张梦洁、何欣怡 新华社音视频部制作"
