    "content": "初秋的四川大凉山，站在高达167米的观音岩大桥上向远处望去，山势一重压着一重。对面的山腰间，几个隧道洞口若隐若现，一段高速公路钻进山腹，又从另一座山间探出头来。 这是在建的西（昌）昭（通）高速老营盘螺旋隧道群。三座隧道、两座桥在群山间首尾相接，进出口直线距离不过1.6公里，高差却超过200米。面对陡峭山势，公路不得不钻进山腹，盘旋、爬升，再向前延伸。 图为观音岩大桥。（受访者供图） 1.6公里，在平原上或许只是一脚油门的距离。在这里，却要架高桥、打长隧，在大山腹中绕上一个圈。 盘山之苦，来自西昌的中铁一局青年建设者…"
