    "author": "刘克英,摄制高国霞",
    "description": "眼下，走进甘肃省庄浪县的苹果园，一张张白色的防雹网在果园上方铺展开来，为即将成熟的苹果保驾护航。65万亩苹果是庄浪县的支柱产业，庄浪县把防雹网建设作为苹果产业高质量发展的关键抓手，逐渐完善果园防灾体系。 作者：刘克英、董春辉、邵娟青 摄制：高国霞 新华社音视频部制作",
