    "author": "马志异,胡秋思",
    "description": "电影《八仙》的热映，让本就热门的悬空寺更火了，目前登临甚至一票难求。在近乎垂直的崖壁上，距地面数十米，且没有大型机械设备，古代工匠是怎么将悬空寺“挂”在崖壁上的？一条视频带你了解悬空寺何以悬空。 记者：马志异、胡秋思 新华社音视频部制作",
