    "pub_date": "2026-08-22 15:23:05",
    "author": "余熙",
    "description": "新华社武汉8月22日电（记者余熙）处暑将近，但“秋老虎”仍然凶猛，武汉暑热持续。18日上午11点，外卖骑手小刘来到武昌万象城取餐，他没有像往常那样钻进商场层层找店，而是走向位于4号门员工通道的爱心接力站，在站内的沙发上稍作休息，两分钟后便从中转员手中取到订单。 “我在这片区域送餐快两年了，以前等电梯、找商家，取餐最长可能要半小时，夏天跑得满身汗。现在到骑手爱心接力站就能取餐，还能停下来喝口水、乘个凉。”小刘说。 据悉，武汉现有约45万名…",
